// Stub for node:fs and node:fs/promises — not available in CF Workers.
const notAvailable = (name: string) => () => { throw new Error(`node:fs.${name} not available in CF Workers`); };

// Sync API stubs
export const readFileSync = notAvailable("readFileSync");
export const writeFileSync = notAvailable("writeFileSync");
export const existsSync = () => false;
export const mkdirSync = notAvailable("mkdirSync");
export const readdirSync = notAvailable("readdirSync");
export const statSync = notAvailable("statSync");
export const unlinkSync = notAvailable("unlinkSync");
export const createReadStream = notAvailable("createReadStream");
export const createWriteStream = notAvailable("createWriteStream");
export const realpath = { native: notAvailable("realpath.native") };
export const realpathSync = { native: notAvailable("realpathSync.native") };

// Async/promises API stubs
const notAvailableAsync = (name: string) => async () => { throw new Error(`node:fs.${name} not available in CF Workers`); };
export const promises = {
  readFile: notAvailableAsync("promises.readFile"),
  writeFile: notAvailableAsync("promises.writeFile"),
  readdir: notAvailableAsync("promises.readdir"),
  mkdir: notAvailableAsync("promises.mkdir"),
  stat: notAvailableAsync("promises.stat"),
  unlink: notAvailableAsync("promises.unlink"),
  access: notAvailableAsync("promises.access"),
  realpath: notAvailableAsync("promises.realpath"),
};

export default { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, statSync,
  unlinkSync, createReadStream, createWriteStream, realpathSync, realpath, promises };
